export function SignupForm({ onSubmit }: { onSubmit: (v: Values) => void }) {
  const [email, setEmail] = useInputValue('');
  const [name, setName] = useInputValue('');
  const [errors, setErrors] = useInputValue<Record<string, string>>({});

  const handleSubmit = () => {
    const next: Record<string, string> = {};
    if (!email.includes('@')) next.email = 'Enter a valid email';
    if (name.trim().length < 2) next.name = 'Name is too short';
    if (name.length > 50) next.name = 'Name is too long';
    setErrors(next);
    if (Object.keys(next).length === 0) onSubmit({ email, name });
  };

  return (
    <Form actions={<Button variant="primary" onClick={handleSubmit}>Subscribe</Button>}>
      <Container>
        <Box>Email</Box>
        <Input value={email} invalid={!!errors.email} onChange={e => setEmail(e.detail.value)} />
        <Box color="text-status-error">{errors.email}</Box>
        <Box>Name</Box>
        <Input value={name} invalid={!!errors.name} onChange={e => setName(e.detail.value)} />
        <Box color="text-status-error">{errors.name}</Box>
      </Container>
    </Form>
  );
}
