export function NotificationSettings({ form, onSave }: {
  form: UseFormReturn<Settings>;
  onSave: (v: Settings) => void;
}) {
  const { register, handleSubmit, setError, formState: { errors } } = form;

  const submit = (v: Settings) => {
    if (!/^\S+@\S+\.\S+$/.test(v.email)) {
      setError('email', { message: 'Bad email' });
      return;
    }
    if (v.digestHour < 0 || v.digestHour > 23) {
      setError('digestHour', { message: 'Hour must be 0-23' });
      return;
    }
    onSave(v);
  };

  return (
    <form onSubmit={handleSubmit(submit)}>
      <label>Email</label>
      <input type="text" {...register('email')} />
      {errors.email && <p>{errors.email.message}</p>}
      <label>Digest hour</label>
      <input type="number" {...register('digestHour', { valueAsNumber: true })} />
      <button type="submit">Save</button>
    </form>
  );
}
```

