Review request: step 2 of the CSV import wizard (column mapping). Context: product wants the Next button disabled until every required column is mapped, plus an error if the same column is mapped twice. The form object is created by the wizard parent with React Hook Form.

```tsx
export function MappingStep({ form, headers, required, onNext }: {
  form: UseFormReturn<{ mapping: Record<string, string> }>;
  headers: string[];
  required: string[];
  onNext: (m: any) => void;
}) {
  const mapping = form.watch('mapping');

  const used = Object.values(mapping).filter(Boolean);
  const hasDuplicate = new Set(used).size !== used.length;
  const missing = required.filter(r => !mapping[r]);
  let error = '';
  if (hasDuplicate) error = 'A column is mapped twice';
  else if (missing.length > 0) error = 'Missing: ' + missing.join(', ');

  return (
    <form>
      {required.map(r => (
        <Box key={r}>
          <Box>{r}</Box>
          <Select
            selectedOption={mapping[r] ? { value: mapping[r] } : null}
            options={headers.map(h => ({ value: h, label: h }))}
            onChange={e => form.setValue(`mapping.${r}`, e.detail.selectedOption.value!)}
          />
        </Box>
      ))}
      {error && <Alert type="error">{error}</Alert>}
      <button disabled={!!error} onClick={() => onNext(mapping)}>Next</button>
    </form>
  );
}
```
